WITH flattened_attrs AS (SELECT id, log_ts, payload_json, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, COALESCE(context['trace'], 'direct') AS trace_or_default, COALESCE(context['version'], 'none') AS version_or_default, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs WHERE log_ts >= '2024-09-16') SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, MAX(log_ts) AS ended_at, COUNT(DISTINCT user_tier) AS distinct_user_tiers FROM flattened_attrs GROUP BY 1 ORDER BY distinct_user_tiers DESC;
